from hypothesis import strategies as st

# Interpretation: product i is in range on the closed interval [T_i, T_i + D_i].
# Print times can be taken as integers (all window endpoints are integers and
# each print occupies a distinct integer slot, since charge time is 1), so the
# reference searches over integer print times, each used by at most one product.

@st.composite
def gen(draw):
    n = draw(st.integers(1, 5))
    mode = draw(st.sampled_from(["random", "all_equal", "duplicates", "sorted"]))
    if mode == "all_equal":
        T = draw(st.integers(1, 4))
        D = draw(st.integers(1, 3))
        pairs = [(T, D)] * n
    elif mode == "duplicates":
        base = [(draw(st.integers(1, 4)), draw(st.integers(1, 3))) for _ in range(2)]
        pairs = [draw(st.sampled_from(base)) for _ in range(n)]
    elif mode == "sorted":
        pairs = sorted(
            (draw(st.integers(1, 6)), draw(st.integers(1, 4))) for _ in range(n)
        )
    else:
        pairs = [(draw(st.integers(1, 6)), draw(st.integers(1, 4))) for _ in range(n)]
    lines = [str(n)] + [f"{T} {D}" for T, D in pairs]
    return "\n".join(lines) + "\n"

def validate(inp):
    t = inp.split()
    if not t:
        return False
    n = int(t[0])
    if not (1 <= n <= 2 * 10**5):
        return False
    if len(t) != 1 + 2 * n:
        return False
    vals = [int(x) for x in t[1:]]
    for i in range(n):
        T, D = vals[2 * i], vals[2 * i + 1]
        if not (1 <= T <= 10**18 and 1 <= D <= 10**18):
            return False
    return True

def ref(inp):
    t = inp.split()
    n = int(t[0])
    items = [(int(t[1 + 2 * i]), int(t[2 + 2 * i])) for i in range(n)]
    best = [0]
    used = set()

    def dfs(i, cnt):
        if cnt + (n - i) <= best[0]:
            return
        if i == n:
            best[0] = max(best[0], cnt)
            return
        T, D = items[i]
        # skip product i
        dfs(i + 1, cnt)
        # print on product i at some free integer time in [T, T+D]
        for x in range(T, T + D + 1):
            if x not in used:
                used.add(x)
                dfs(i + 1, cnt + 1)
                used.discard(x)

    dfs(0, 0)
    return str(best[0])
