from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    items = []
    for _ in range(n):
        t = draw(st.integers(1, 6))
        d = draw(st.integers(1, 5))
        items.append((t, d))
    # Edge-case bias: sometimes force all-equal intervals or duplicates.
    if draw(st.booleans()):
        base = draw(st.tuples(st.integers(1, 6), st.integers(1, 5)))
        items = [base] * n
    lines = [str(n)] + [f"{t} {d}" for t, d in items]
    return "\n".join(lines) + "\n"


def validate(inp):
    lines = inp.strip().split("\n")
    if not lines:
        return False
    try:
        n = int(lines[0])
    except ValueError:
        return False
    if not (1 <= n <= 2 * 10**5):
        return False
    if len(lines) != n + 1:
        return False
    for i in range(1, n + 1):
        parts = lines[i].split()
        if len(parts) != 2:
            return False
        t, d = int(parts[0]), int(parts[1])
        if not (1 <= t <= 10**18 and 1 <= d <= 10**18):
            return False
    return True


def ref(inp):
    # Brute force. Integer print times suffice: for any valid schedule with
    # real print times in closed integer intervals, replacing each time t by
    # ceil(t) keeps it inside its interval and keeps gaps >= 1.
    # So the problem reduces to: maximize number of products assigned
    # pairwise-distinct integer times within [T_i, T_i + D_i].
    lines = inp.strip().split("\n")
    n = int(lines[0])
    items = []
    for i in range(1, n + 1):
        t, d = map(int, lines[i].split())
        items.append((t, t + d))

    best = 0

    def rec(idx, used, count):
        nonlocal best
        if count + (n - idx) <= best:
            return
        if idx == n:
            if count > best:
                best = count
            return
        # Option: skip this product
        rec(idx + 1, used, count)
        # Option: print on this product at some unused integer time in its interval
        lo, hi = items[idx]
        for tm in range(lo, hi + 1):
            if tm not in used:
                used.add(tm)
                rec(idx + 1, used, count + 1)
                used.remove(tm)

    rec(0, set(), 0)
    return str(best)
