from hypothesis import strategies as st
from itertools import permutations, combinations

@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    pairs = draw(st.lists(
        st.tuples(st.integers(1, 8), st.integers(1, 6)),
        min_size=n, max_size=n))
    lines = [str(n)] + [f"{t} {d}" for t, d in pairs]
    return "\n".join(lines) + "\n"

def validate(inp):
    lines = inp.strip().split("\n")
    if not lines:
        return False
    try:
        n = int(lines[0])
    except ValueError:
        return False
    if not (1 <= n <= 2 * 10**5):
        return False
    if len(lines) != n + 1:
        return False
    for i in range(1, n + 1):
        parts = lines[i].split()
        if len(parts) != 2:
            return False
        try:
            t, d = int(parts[0]), int(parts[1])
        except ValueError:
            return False
        if not (1 <= t <= 10**18 and 1 <= d <= 10**18):
            return False
    return True

def ref(inp):
    lines = inp.strip().split("\n")
    n = int(lines[0])
    items = []
    for i in range(1, n + 1):
        t, d = map(int, lines[i].split())
        # product is printable at any real time in [t, t+d]
        items.append((t, t + d))
    best = 0
    # Try every subset; a subset is feasible if some ordering of its
    # products, each printed at the earliest allowed time (>= previous + 1,
    # >= its entry time), finishes every product within its leave time.
    for mask in range(1 << n):
        idx = [i for i in range(n) if mask >> i & 1]
        k = len(idx)
        if k <= best:
            continue
        feasible = False
        for perm in permutations(idx):
            cur = None
            ok = True
            for i in perm:
                t, e = items[i]
                tm = t if cur is None else max(cur + 1, t)
                if tm > e:
                    ok = False
                    break
                cur = tm
            if ok:
                feasible = True
                break
        if feasible:
            best = k
    return str(best)
